stack=[]; pairs={}
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')': j=stack.pop(); pairs[j]=i; pairs[i]=j
def fold(seq):
    fc=RNA.fold_compound(seq); return fc.mfe()
def fold_constrained_target(seq):
    fc=RNA.fold_compound(seq)
    # force all target pairs
    for i in range(73):
        if target[i]=='(':
            j=pairs[i]
            fc.hc_add_bp(i+1,j+1, RNA.CONSTRAINT_INT_RNA | RNA.CONSTRAINT_DB_DEFAULT)
    fc.hc_add_bp(18,56, RNA.CONSTRAINT_INT_RNA | RNA.CONSTRAINT_DB_DEFAULT) if False else None
    ss,mfe=fc.mfe(); return ss,mfe

seq="AAGCGCGCGCAAAAAAAGAGGGCCCAAAAGGGCCCAGGGGCCCAAAAGGGCCCCACAAAAAAAGCGCGCGCAA"
ss,mfe=fold(seq)
print("unconstrained MFE:",ss,mfe)
# force target via HC
fc=RNA.fold_compound(seq)
def force_target():
    fc2=RNA.fold_compound(seq)
    for i in range(73):
        if target[i]=='(':
            j=pairs[i]
            fc2.hc_add_bp(i+1,j+1)
        elif target[i]=='.':
            fc2.hc_add_from_db(i+1, RNA.CONSTRAINT_DB_DOT)
    return fc2.mfe()
ss2,mfe2=force_target()
print("forced target:",ss2,mfe2)
print("gap:",mfe2-mfe)
