import RNA, itertools, random
target = "..((((((((.......(.((((((....)))))).(((((((....))))))).).......)))))))).."
def comp(c): return {'G':'C','C':'G','A':'U','U':'A'}[c]
stack=[]; pairs={}
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')': j=stack.pop(); pairs[j]=i; pairs[i]=j
def build(stem_outer, stem1, stem2, loneL, loneR, leftloop, rightloop, loop4a, loop4b, p0,p1,p18,p35,p54,p71,p72):
    seq=['.']*73
    def fillstem(a,b,pat):
        for i in range(b-a+1):
            x=a+i; y=pairs[x]
            seq[x]=pat[i%len(pat)]; seq[y]=comp(pat[i%len(pat)])
    fillstem(2,9,stem_outer); fillstem(19,24,stem1); fillstem(36,42,stem2)
    seq[17]=loneL; seq[55]=loneR
    for i,ch in enumerate(leftloop): seq[10+i]=ch
    for i,ch in enumerate(rightloop): seq[56+i]=ch
    for i,ch in enumerate(loop4a): seq[25+i]=ch
    for i,ch in enumerate(loop4b): seq[43+i]=ch
    for pos,ch in [(0,p0),(1,p1),(18,p18),(35,p35),(54,p54),(71,p71),(72,p72)]:
        seq[pos]=ch
    return ''.join(seq)
def fold(seq):
    fc=RNA.fold_compound(seq); return fc.mfe()
# Exhaustive over positions 16,18,54,56 (4^4=256) plus lone pair (2), keep loops all A
hits=[]
for loneL in ['G','C']:
    loneR=comp(loneL)
    for p16 in 'ACGU':
        for p18 in 'ACGU':
            for p54 in 'ACGU':
                for p56 in 'ACGU':
                    leftloop = 'AAAAA'+p16  # positions 10-15=A, 16=p16
                    rightloop= p56+'AAAAAA' # pos56=p56, 57-62=A
                    seq=build("GCGCGCGC","GGGCCC","GGGGCCC",loneL,loneR,leftloop,rightloop,"AAAA","AAAA",'A','A',p18,'A',p54,'A','A')
                    ss,mfe=fold(seq)
                    if ss==target:
                        hits.append((seq,mfe)); print("HIT",seq,mfe)
print("hits",len(hits))
EOF
